<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/schema.php';$schema=dental_schema($pdo);$labId=$schema->labId();$serviceCol=$schema->serviceId();$serviceName=$schema->serviceName();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$published=$schema->status('valide');
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$lab=null;if($id){$q=$pdo->prepare("SELECT `$labId` id,nom_laboratoire,nom_gerant,telephone,email,adresse,ville,site_web,instagram,description FROM laboratoire WHERE `$labId`=? AND statut=? LIMIT 1");$q->execute([$id,$published]);$lab=$q->fetch();}if(!$lab)http_response_code(404);$images=[];$services=[];$similar=[];$phone='';$webUrl='';
if($lab){$q=$pdo->prepare("SELECT `$imagePath` FROM image_laboratoire WHERE laboratoire_id=? ORDER BY `$imageId`");$q->execute([$id]);$images=$q->fetchAll(PDO::FETCH_COLUMN);$q=$pdo->prepare("SELECT s.`$serviceName` FROM service s JOIN laboratoire_service ls ON ls.service_id=s.`$serviceCol` WHERE ls.laboratoire_id=? ORDER BY s.`$serviceName`");$q->execute([$id]);$services=$q->fetchAll(PDO::FETCH_COLUMN);$q=$pdo->prepare("SELECT l.`$labId` id,l.nom_laboratoire,l.ville,(SELECT i.`$imagePath` FROM image_laboratoire i WHERE i.laboratoire_id=l.`$labId` ORDER BY i.`$imageId` LIMIT 1) photo FROM laboratoire l WHERE l.statut=? AND l.ville=? AND l.`$labId`<>? ORDER BY l.`$labId` DESC LIMIT 3");$q->execute([$published,$lab['ville'],$id]);$similar=$q->fetchAll();$phone=preg_replace('/[^0-9+]/','',(string)$lab['telephone']);foreach(['site_web','instagram'] as $field){$url=trim((string)($lab[$field]??''));if($url!==''&&filter_var($url,FILTER_VALIDATE_URL)&&in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true)&&$field==='site_web')$webUrl=$url;}}
$pageTitle=$lab?($lab['nom_laboratoire'].' — DentalLink Morocco'):'Laboratoire introuvable — DentalLink';$pageDescription=$lab?'Coordonnées, photos et services de '.$lab['nom_laboratoire'].' à '.$lab['ville'].'.':'Fiche introuvable dans l’annuaire.';$pageStyles=['assets/css/public.css'];$loadInterFont=true;require __DIR__.'/includes/header.php';require_once __DIR__.'/includes/public-nav.php';
?>
<?php if(!$lab):?><main class="container"><section class="not-found"><span class="eyebrow">Erreur 404</span><h1>Laboratoire introuvable</h1><p>Cette fiche n’existe pas ou n’est pas publiée dans l’annuaire.</p><a class="btn btn-primary" href="laboratoires.php">Retour aux laboratoires</a></section></main><?php else:?><main><section class="page-hero"><div class="container"><div class="breadcrumb"><a href="index.php">Accueil</a>　›　<a href="laboratoires.php">Laboratoires</a>　›　<?=e($lab['nom_laboratoire'])?></div><span class="eyebrow">Laboratoire validé</span><h1 style="margin-top:13px"><?=e($lab['nom_laboratoire'])?></h1><p>⌖ <?=e($lab['ville'])?> · <?=e($lab['adresse'])?></p></div></section><div class="container details-layout"><div><?php if($images):?><img class="gallery-main" id="gallery-main" src="<?=e($images[0])?>" alt="Photo de <?=e($lab['nom_laboratoire'])?>"><?php if(count($images)>1):?><div class="thumbs" aria-label="Galerie de photos"><?php foreach($images as $n=>$image):?><button class="thumb-button" type="button" data-src="<?=e($image)?>" aria-label="Afficher la photo <?=$n+1?>"><img class="thumb <?=$n===0?'active':''?>" src="<?=e($image)?>" alt="Miniature <?=$n+1?>"></button><?php endforeach;?></div><?php endif;?><?php endif;?><h2 class="details-title">À propos du laboratoire</h2><p class="details-copy"><?=e($lab['description']?:'Aucune description disponible.')?></p><h2>Services proposés</h2><div class="service-list"><?php foreach($services as $service):?><span class="chip"><?=e($service)?></span><?php endforeach;?><?php if(!$services):?><span class="details-location">Services non renseignés.</span><?php endif;?></div></div><aside class="details-card"><h3>Contacter le laboratoire</h3><div class="contact-row"><span class="contact-mark">⌖</span><span><?=e($lab['adresse'])?><br><strong><?=e($lab['ville'])?></strong></span></div><div class="contact-row"><span class="contact-mark">☎</span><a href="tel:<?=e($phone)?>"><?=e($lab['telephone'])?></a></div><div class="contact-row"><span class="contact-mark">✉</span><a href="mailto:<?=e($lab['email'])?>"><?=e($lab['email'])?></a></div><?php if($webUrl):?><div class="contact-row"><span class="contact-mark">↗</span><a href="<?=e($webUrl)?>" target="_blank" rel="noopener noreferrer">Site web</a></div><?php endif;?><a class="btn btn-primary" href="tel:<?=e($phone)?>">Appeler le laboratoire</a><a class="btn btn-soft" href="mailto:<?=e($lab['email'])?>">Envoyer un e-mail</a><a class="btn btn-soft" href="laboratoires.php">← Retour à l’annuaire</a></aside></div><?php if($similar):?><section class="container similar"><div class="section-head"><div><span class="kicker">À proximité de votre recherche</span><h2>Laboratoires similaires</h2></div><a class="textlink" href="laboratoires.php">Tout l’annuaire →</a></div><div class="cards"><?php foreach($similar as $other):?><article class="lab-card"><?php if($other['photo']):?><img class="lab-photo" src="<?=e($other['photo'])?>" alt="Laboratoire <?=e($other['nom_laboratoire'])?>"><?php endif;?><div class="lab-content"><h3 class="lab-title"><?=e($other['nom_laboratoire'])?></h3><div class="lab-location">⌖ <?=e($other['ville'])?></div><a class="card-link" href="laboratoire-details.php?id=<?=$other['id']?>">Voir le laboratoire →</a></div></article><?php endforeach;?></div></section><?php endif;?></main><?php endif;?>
